def lands(d: int) -> bool:
    # Rule: d is a perfect square or d is a prime number
    if d < 2:
        return d == 1  # 1 is a perfect square
    # Check perfect square
    root = int(d**0.5)
    if root * root == d:
        return True
    # Check prime
    if d % 2 == 0:
        return False
    for i in range(3, int(d**0.5) + 1, 2):
        if d % i == 0:
            return False
    return True

